"""Build the source-paired tornado assembly player from its timeline."""
from pathlib import Path
import json,re
from html import escape
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'integrated'
s=json.loads((OUT/'shot.json').read_text())
css='\n*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#171512;font:17px/1.5 system-ui,sans-serif}.wrap{max-width:1080px;margin:auto;padding:20px}a{color:inherit}h1{font-size:clamp(32px,7vw,62px);line-height:1;margin:22px 0 12px}nav{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}.meta{font-size:14px;color:#625b50}.badge{display:inline-block;background:#ef9f3a;padding:4px 9px;font-size:12px;letter-spacing:.04em;font-weight:700}.player{background:#fffdf7;border:1px solid #d5caba;border-radius:8px;overflow:hidden}video{display:block;width:100%;max-height:65vh;background:#fffdf7}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button{font:inherit;border:1px solid #aaa18f;background:#fffdf7;color:#171512;border-radius:5px;padding:9px 14px;cursor:pointer}button[aria-pressed=true]{background:#171512;color:#fffdf7}.keys{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;border:1px solid #d5caba;background:#fffdf7;border-radius:6px;overflow:hidden}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pair img{width:100%;display:block}figcaption{padding:10px;font-size:13px}summary{cursor:pointer}details{margin:22px 0}footer{margin:28px 0;border-top:1px solid #d5caba;padding-top:16px;font-size:14px}@media(max-width:600px){.keys{grid-template-columns:1fr}.wrap{padding:14px}button{font-size:15px}}\n'
script="\nconst v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{})},{once:true});v.load()});\n"
cards=[]
for k,f in enumerate(s['keys'],1):
 t=s['frames'][f]['source_time'];cards.append(f'<figure><div class="pair"><img src="source-{k:02d}.jpg" alt="Source at {t:.3f} seconds"><img src="key-{k:02d}.png" alt="Integrated cartoon key {k}"></div><figcaption>Key {k} · source {t:.3f} s · frame {f}</figcaption></figure>')
note=s.get('review_note','Source contour and normal-speed motion review pending.');badge='ASSEMBLED REVIEW COPY' if s.get('review_status') in ('review_pending','still_pass_playback_pending') else 'SOURCE POSE NEEDS REPAIR'
review='review-v3.json' if (OUT/'review-v3.json').exists() else 'review-v2.json' if (OUT/'review-v2.json').exists() else 'review-v1.json'
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tornado · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>'''+css+'''</style><body><main class="wrap"><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../wave2-keyframes.html">Wave 2 clips</a><a href="../index.html">Earlier isolated keys</a></nav><h1>Tornado beyond the street.</h1><p class="meta">'''+str(s['frame_count'])+''' rendered frames · 24 fps · six integrated keys · '''+format(s['duration'],'.3f')+''' seconds</p><p><span class="badge">'''+badge+'''</span></p><div class="player"><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video></div><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="meta">'''+escape(note)+'''</p><p class="meta">The original three-stroke funnel changes contour behind one source-framed street and tree drawing. Utility-pole and tree landmarks guide the camera shift. No spin or ground contact is invented.</p><h2>Six moments, assembled.</h2><section class="keys">'''+''.join(cards)+'''</section><details><summary>References and review</summary><p>Quick, Draw! key 6522189199179776. Original three strokes retain their point correspondence through every frame. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0. Street, cars, trees and utility lines drawn once by agent against the archive frame.</p><p>Archive: <a href="'''+escape(s['source']['page_url'])+'''">Tornado</a>, clip-relative 0.23357–3.26993 s. Archive rights were not provided in the candidate manifest.</p><p><a href="shot.json">Timeline and source anchors</a> · <a href="assembly-checks.json">Checks</a> · <a href="'''+review+'''">Independent still review</a> · <a href="design.png">Original doodle</a> · <a href="sam/audit.jpg">SAM audit</a> · <a href="sam/provenance.json">Mask provenance</a></p><p>The SAM output switches between sky and a foreground tree despite high model estimates. It is not a valid tornado silhouette, so no numeric mask-fit pass is claimed. Recognition and normal-speed playback approval are pending. No training ran.</p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download comparison</a></footer></main><script>'''+script+'''</script></html>'''
(OUT/'index.html').write_text(html)
